
CREATE TABLE IF NOT EXISTS "projects" ("id" TEXT PRIMARY KEY, "kind" TEXT NOT NULL, "customer_id" TEXT NOT NULL, "customer_name" TEXT, "customer_email" TEXT, "designer_slug" TEXT NOT NULL, "designer_user_id" TEXT, "design_slug" TEXT, "title" TEXT NOT NULL, "brief" TEXT NOT NULL, "room" TEXT, "wall_size" TEXT, "budget" TEXT, "attachments" TEXT DEFAULT '[]', "status" TEXT DEFAULT 'requested', "quote_id" TEXT, "fee" REAL, "days" INTEGER, "commission_pct" REAL, "approved_at" TEXT, "paid_at" TEXT, "due_at" TEXT, "order_id" TEXT, "final_key" TEXT, "final_name" TEXT, "final_size" INTEGER, "final_link" TEXT, "final_note" TEXT, "delivered_at" TEXT, "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), "updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS "project_quotes" ("id" TEXT PRIMARY KEY, "project_id" TEXT NOT NULL, "designer_user_id" TEXT NOT NULL, "designer_slug" TEXT NOT NULL, "fee" REAL NOT NULL, "days" INTEGER NOT NULL, "note" TEXT, "status" TEXT DEFAULT 'sent', "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), "updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS "project_messages" ("id" TEXT PRIMARY KEY, "project_id" TEXT NOT NULL, "designer_user_id" TEXT NOT NULL, "sender_id" TEXT NOT NULL, "sender_role" TEXT NOT NULL, "body" TEXT NOT NULL, "attachments" TEXT DEFAULT '[]', "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS "blocked_messages" ("id" TEXT PRIMARY KEY, "user_id" TEXT, "project_id" TEXT, "reason" TEXT, "body" TEXT, "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS "notifications" ("id" TEXT PRIMARY KEY, "user_id" TEXT NOT NULL, "kind" TEXT, "title" TEXT NOT NULL, "body" TEXT, "link" TEXT, "read_at" TEXT, "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS "notifications_user" ON "notifications" ("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "project_messages_p" ON "project_messages" ("project_id", "created_at");
CREATE INDEX IF NOT EXISTS "project_quotes_p" ON "project_quotes" ("project_id");
